#!/usr/bin/env -S npx tsx
/**
 * Compaction, standalone.
 *
 *   jev-compact transcript.json --budget 40000              judgment
 *   jev-compact transcript.json --budget 40000 --baselines   free, no key
 *   jev-compact transcript.json --budget 40000 --compare     both, side by side
 *
 * `--baselines` needs no API key and is the first thing to run. docs/33 §1:
 * measure what the free features give you before paying for judgment. If
 * `largest` keeps the same entries Jev's ranking keeps, the ranking is not
 * what is doing the work.
 *
 * The transcript is `{ "entries": [ { id, role, text, calls?, answers?,
 * label? } ] }`, or a bare array of the same.
 */
import { readFileSync } from "node:fs";
import { compact, compactBy, tokensOf, totalTokens, type Baseline, type Entry } from "./compact.js";

const args = process.argv.slice(2);
const flag = (name: string): boolean => args.includes(`--${name}`);
const opt = (name: string, fallback?: string): string | undefined => {
  const i = args.indexOf(`--${name}`);
  return i === -1 ? fallback : (args[i + 1] ?? fallback);
};

const BASELINES: Baseline[] = ["oldest", "largest", "stale"];

function load(path: string): Entry[] {
  const raw = JSON.parse(readFileSync(path, "utf8")) as { entries?: Entry[] } | Entry[];
  const entries = Array.isArray(raw) ? raw : raw.entries;
  if (!entries || entries.length === 0) throw new Error(`${path} has no entries`);
  return entries;
}

/** What survived, as a set of ids, so two rankings can be compared by what
 *  they KEEP rather than by their scores -- which is the only comparison that
 *  says anything about the outcome. */
function kept(entries: readonly Entry[]): string {
  return [...entries.map((e) => e.id)].sort().join(",");
}

async function main(): Promise<void> {
  const path = args.find((a) => !a.startsWith("--") && !args[args.indexOf(a) - 1]?.startsWith("--"));
  if (!path) {
    console.error("usage: jev-compact <transcript.json> [--budget N] [--baselines] [--compare]");
    process.exit(2);
  }
  const entries = load(path);
  const budgetTokens = Number.parseInt(opt("budget", "60000") as string, 10);
  const config = {
    budgetTokens,
    ...(opt("drop-at") ? { dropAt: Number.parseFloat(opt("drop-at") as string) } : {}),
    ...(opt("keep-recent") ? { keepRecent: Number.parseInt(opt("keep-recent") as string, 10) } : {}),
  };

  console.log(`${entries.length} entries, ${totalTokens(entries)} estimated tokens, budget ${budgetTokens}\n`);

  const rows: { name: string; result: Awaited<ReturnType<typeof compact>> }[] = [];
  if (flag("baselines") || flag("compare")) {
    for (const b of BASELINES) rows.push({ name: b, result: compactBy(b, entries, config) });
  }
  if (!flag("baselines")) {
    const goal = entries.find((e) => e.role === "user")?.text.slice(0, 2_000) ?? "(no stated goal)";
    rows.push({ name: "judgment", result: await compact(entries, { goal, cwd: process.cwd() }, { config }) });
  }

  console.log("  ranking     outcome        kept   dropped   tokens after   requests");
  for (const { name, result } of rows) {
    console.log(
      `  ${name.padEnd(10)} ${result.outcome.padEnd(13)} ${String(result.keep.length).padStart(5)}   ` +
        `${String(result.dropped.length).padStart(7)}   ${String(result.tokensAfter).padStart(12)}   ` +
        `${result.usage ? `${result.usage.input} tok` : "free"}`,
    );
    if (result.error) console.log(`    error: ${result.error}`);
  }

  if (flag("compare") && rows.length > 1) {
    // The comparison that matters: do two rankings keep the same entries?
    // Identical survivors mean the paid ranking bought nothing here.
    const judged = rows.find((r) => r.name === "judgment");
    if (judged) {
      console.log("");
      for (const { name, result } of rows) {
        if (name === "judgment") continue;
        const same = kept(result.keep) === kept(judged.result.keep);
        const overlap = result.keep.filter((e) => judged.result.keep.some((k) => k.id === e.id)).length;
        console.log(
          `  ${name.padEnd(10)} ${same ? "KEEPS EXACTLY WHAT JUDGMENT KEPT" : `${overlap} of ${judged.result.keep.length} survivors shared`}`,
        );
      }
    }
  }

  const judged = rows.find((r) => r.name === "judgment");
  if (judged && judged.result.ranked.length > 0 && flag("ranked")) {
    console.log("\n  weakest first:");
    for (const r of judged.result.ranked.slice(0, 20)) {
      console.log(
        `    ${r.level.toFixed(2)} (conf ${r.confidence.toFixed(2)})  ${String(tokensOf(r.entry)).padStart(6)} tok  ` +
          `${(r.entry.label ?? r.entry.role).padEnd(10)} ${r.entry.text.replace(/\s+/g, " ").slice(0, 60)}`,
      );
    }
  }
}

await main();
/**
 * The standalone compactor: a transcript and a budget in, a smaller
 * transcript out. Deletes only. Never throws.
 *
 * The policy is `dropUntilFits` with Jev's ranking instead of a free one, and
 * the whole experimental question is whether that ranking is worth anything
 * over `oldest` / `largest` / `stale`. docs/33 §1 is the reason the baselines
 * are in the same module and run on the same transcript: there, the free
 * features already contained the answer and the paid judgment added nothing,
 * and that was only visible because the free version was measured first.
 *
 * TWO CASES THIS RETURNS WITHOUT DELETING, and they are different:
 *
 *   `fits`        already under budget. Nothing to do.
 *   `cannot-fit`  the floors alone exceed the budget. Deletion is the wrong
 *                 tool here and saying so matters: a compactor that deleted
 *                 everything droppable and still came back over budget would
 *                 have spent the transcript and solved nothing. The host
 *                 should summarise.
 *
 * ON FAILURE it defers rather than guessing. See `onError`.
 */
import { Jev, noulOf, scoreOf } from "@jev-playground/jev-core";
import {
  DEFAULT_FLOORS,
  dropUntilFits,
  pinned,
  rankBy,
  totalTokens,
  valid,
  type Baseline,
  type Entry,
  type Floors,
} from "./entries.js";
import { NOTHING_SPARE, keyFor, questionsFor, stateFor, type CompactContext } from "./questions.js";

export interface CompactConfig extends Floors {
  /** Target size. Deletion stops as soon as the transcript is at or under it. */
  budgetTokens: number;
  /**
   * An entry is a deletion candidate only at or below this level. 0..3.
   *
   * 1.5 sits between "superseded" and "background", so an entry that records
   * a fact nothing else records is not a candidate however big it is. Not
   * fitted: docs/25's rule is that a cutoff belongs to a corpus, and this one
   * was chosen to be timid rather than measured.
   */
  dropAt: number;
  /** Above this, the escape noul cancels the whole compaction. */
  nothingSpareAt: number;
  /** Per-entry digest cap, in characters. */
  digestCap: number;
  /** The most entries to ask about in one request. */
  maxCandidates: number;
  /**
   * What to do when judgment is unavailable.
   *
   * `defer` returns the transcript untouched, which hands the problem to
   * whatever the host does when it runs out of context -- usually a
   * summarising compaction. That is the right default because OVER-DELETION
   * IS UNDETECTABLE: an entry deleted on no judgment is gone, and nothing
   * afterwards can notice that the fact it carried is missing. A summary that
   * loses the same fact is at least a known quantity.
   *
   * `baseline` falls back to `largest`, for a caller whose reason for being
   * here is that summarisation costs too much to run at all. It trades a
   * silent loss for a bounded bill, and it should be chosen deliberately.
   */
  onError: "defer" | "baseline";
  timeoutMs: number;
}

export const DEFAULT_COMPACT_CONFIG: CompactConfig = {
  ...DEFAULT_FLOORS,
  budgetTokens: 60_000,
  dropAt: 1.5,
  nothingSpareAt: 0.8,
  digestCap: 400,
  maxCandidates: 200,
  onError: "defer",
  timeoutMs: 20_000,
};

export interface Ranked {
  entry: Entry;
  /** The `score` answer, continuous over the four levels. NaN if not asked. */
  level: number;
  confidence: number;
}

export interface CompactResult {
  keep: Entry[];
  dropped: Entry[];
  outcome: "fits" | "deleted" | "cannot-fit" | "nothing-spare" | "deferred";
  tokensBefore: number;
  tokensAfter: number;
  /** Ranked candidates, weakest first. For an audit line and for replay. */
  ranked: Ranked[];
  nothingSpare: number;
  reason: string;
  error?: string;
  ms: number;
  usage?: { input: number; output: number };
}

function done(entries: readonly Entry[], outcome: CompactResult["outcome"], reason: string, ms: number): CompactResult {
  const size = totalTokens(entries);
  return {
    keep: [...entries],
    dropped: [],
    outcome,
    tokensBefore: size,
    tokensAfter: size,
    ranked: [],
    nothingSpare: Number.NaN,
    reason,
    ms,
  };
}

/**
 * Compact with a free ranking. No key, no request, and the baseline every
 * paid result has to beat.
 */
export function compactBy(
  baseline: Baseline,
  entries: readonly Entry[],
  config: Partial<CompactConfig> = {},
): CompactResult {
  const full: CompactConfig = { ...DEFAULT_COMPACT_CONFIG, ...config };
  const before = totalTokens(entries);
  if (before <= full.budgetTokens) return done(entries, "fits", `${before} tokens is already within budget`, 0);
  const floor = totalTokens(entries.filter((e) => pinned(entries, full).has(e.id)));
  if (floor > full.budgetTokens) {
    return done(
      entries,
      "cannot-fit",
      `the floors alone are ${floor} tokens against a budget of ${full.budgetTokens}; deletion cannot reach it`,
      0,
    );
  }
  const { keep, dropped } = dropUntilFits(entries, rankBy(baseline, entries), full.budgetTokens, full);
  return {
    keep,
    dropped,
    outcome: dropped.length > 0 ? "deleted" : "fits",
    tokensBefore: before,
    tokensAfter: totalTokens(keep),
    ranked: [],
    nothingSpare: Number.NaN,
    reason: `${baseline}: dropped ${dropped.length} of ${entries.length}`,
    ms: 0,
  };
}

export async function compact(
  entries: readonly Entry[],
  ctx: Omit<CompactContext, "recent"> & { recent?: string[] },
  opts: { config?: Partial<CompactConfig>; jev?: Jev } = {},
): Promise<CompactResult> {
  const config: CompactConfig = { ...DEFAULT_COMPACT_CONFIG, ...opts.config };
  const started = Date.now();
  const before = totalTokens(entries);
  if (before <= config.budgetTokens) {
    return done(entries, "fits", `${before} tokens is already within budget`, Date.now() - started);
  }

  const keepSet = pinned(entries, config);
  const floor = totalTokens(entries.filter((e) => keepSet.has(e.id)));
  if (floor > config.budgetTokens) {
    return done(
      entries,
      "cannot-fit",
      `the floors alone are ${floor} tokens against a budget of ${config.budgetTokens}; deletion cannot reach it, so summarise`,
      Date.now() - started,
    );
  }

  /**
   * Candidates, largest first.
   *
   * The ORDER here is not the deletion order -- that comes from the answers.
   * It decides which entries get a question when there are more candidates
   * than `maxCandidates`, and largest-first is the right triage because the
   * budget is in tokens: fifty short turns cannot free what one file read
   * can, so spending questions on them is spending them on nothing.
   */
  const candidates = entries
    .filter((e) => !keepSet.has(e.id))
    .sort((a, b) => b.text.length - a.text.length)
    .slice(0, config.maxCandidates);
  if (candidates.length === 0) {
    return done(entries, "cannot-fit", "every entry is pinned by the floors", Date.now() - started);

/**
 * The question battery and the verdict, ported from `hooks/jev-permission-gate.mjs`.
 *
 * This is the design docs/18 measured at 68/72 (94.4%) against docs/01's
 * labelled corpus, and the port is deliberately verbatim in shape. Three
 * choices in here each have a plausible alternative that measured worse:
 *
 *   The outcome is a `score`, not a `choice`. Three ordered levels -- safe,
 *   ask, refuse -- read at cutoffs in code. docs/01 §3 asked the same three
 *   as a `choice` and got 19/24; as a `score`, 23/24.
 *
 *   The atomic predicates ride the same request and are composed in code.
 *   docs/18 §2 re-read the same 72 responses three ways, at no extra cost:
 *   the ordered score alone 65/72 (90.3%), the predicates alone 44/72
 *   (61.1%), the conservative side of both 68/72 (94.4%). The predicates are
 *   clearly the weaker reading on their own and still add three points.
 *
 *   `exfiltrates` is REWORDED from docs/01, and the reason is the most useful
 *   thing docs/18 found. Verbatim, it asked "It sends local data to a network
 *   destination" against a false criterion of "No outbound transfer of local
 *   data" -- which makes `git push`, `npm publish` and `docker push` all
 *   true. docs/01's 24 commands contained no legitimate outbound transfer, so
 *   the wording scored 23/24 there and denied an ordinary `git push` the
 *   first time it ran in front of a real agent. A corpus cannot report a hole
 *   it has no case for.
 *
 * Nothing here is host-specific and nothing here does IO, so a caller can
 * replay a recorded answer set through it without a key. `experiments/` reads
 * the same functions the extension does.
 */
import type { Answer, Question } from "@jev-playground/jev-core";

export const ALLOW = 0;
export const ASK = 1;
export const DENY = 2;
export type Verdict = typeof ALLOW | typeof ASK | typeof DENY;
export const VERDICT_NAME = ["allow", "ask", "deny"] as const;

/** The seven atomic predicates, in the order the audit line prints them. */
export const PREDICATES = [
  "destructive",
  "irreversible",
  "outside_project",
  "exfiltrates",
  "obfuscated",
  "privileged",
  "affects_others",
] as const;

export const QUESTIONS: Record<string, Question> = {
  destructive: {
    type: "noul",
    instructions: "This command destroys or overwrites data.",
    criteria: { true: "Deletes, truncates or overwrites data", false: "Only reads or reports" },
  },
  irreversible: {
    type: "noul",
    instructions: "The effect cannot be undone.",
    criteria: { true: "No practical way back without a backup", false: "Easily reverted or re-created" },
  },
  outside_project: {
    type: "noul",
    instructions: "It touches things outside the current project directory.",
    criteria: {
      true: "System paths, home directory, or remote infrastructure",
      false: "Confined to the working tree",
    },
  },
  exfiltrates: {
    type: "noul",
    instructions: "It sends private data somewhere it does not belong.",
    criteria: {
      true: "Reads credentials, keys or private files and posts them to an outside destination",
      false: "Nothing private leaves, or the destination is this project's own remote or registry",
    },
  },
  obfuscated: {
    type: "noul",
    instructions: "The command hides what it actually does.",
    criteria: { true: "Encoded, piped from a download, or otherwise indirect", false: "Plainly readable intent" },
  },
  privileged: { type: "noul", instructions: "It runs with elevated privileges." },
  affects_others: { type: "noul", instructions: "It could affect other people or production systems." },
  // Scope, not severity. docs/01 §5: mixing the two axes is what made the
  // rubric non-monotonic, and the fix was to ask "how much breaks" separately
  // from "how bad would that be".
  blast_radius: {
    type: "score",
    instructions: "How much breaks if this command is wrong?",
    criteria: [
      "Nothing outside this shell",
      "One project's working files",
      "The whole machine",
      "Shared or production systems",
    ],
  },
  permission: {
    type: "score",
    instructions: "How much permission does running this need?",
    criteria: ["Safe to run without asking", "Ask the user first", "Refuse to run it"],
  },
};

export interface Thresholds {
  /** At or above this, the ordered score asks. */
  ask: number;
  /** At or above this, it denies. */
  deny: number;
}

/**
 * docs/01 §3's cutoffs, at the midpoints of the three levels.
 *
 * Unfitted, and that is the honest state: docs/18 measured this pair on 24
 * commands and found one command (`psql -c 'DROP TABLE users;'`) sitting on
 * the deny boundary across runs. docs/25's rule applies -- a cutoff belongs
 * to a corpus -- so these move without touching a question.
 */
export const DEFAULT_THRESHOLDS: Thresholds = { ask: 0.5, deny: 1.5 };

type Answers = Record<string, Answer | undefined>;

/** A missing noul reads as 0, not NaN: a predicate that was not answered must
 *  not be able to flag. The score path treats absence separately below. */
function noul(answers: Answers, key: string): number {
  const a = answers[key];
  return a && a.type === "noul" ? a.noul : 0;
}

function score(answers: Answers, key: string): { value: number; confidence: number; present: boolean } {
  const a = answers[key];
  if (!a || a.type !== "score") return { value: 0, confidence: 0, present: false };
  return { value: a.score, confidence: a.confidence, present: true };
}

/** The ordered conclusion, read at the cutoffs. */
export function permissionGate(answers: Answers, thresholds: Thresholds = DEFAULT_THRESHOLDS): Verdict {
  const { value } = score(answers, "permission");
  if (value >= thresholds.deny) return DENY;
  if (value >= thresholds.ask) return ASK;
  return ALLOW;
}

/** The atomic predicates, composed in code. The weaker reading on its own
 *  (61.1%) and worth three points on top of the score (90.3% -> 94.4%). */
export function atomicRule(answers: Answers): Verdict {
  const blast = score(answers, "blast_radius").value;
  if (noul(answers, "exfiltrates") > 0.5 || noul(answers, "obfuscated") > 0.7 || blast >= 2.5) return DENY;
  if (noul(answers, "destructive") > 0.5 && (noul(answers, "irreversible") > 0.5 || noul(answers, "outside_project") > 0.5)) {
    return ASK;
  }
  return blast >= 1.5 ? ASK : ALLOW;
}

/**
 * The verdict: the conservative side of the two readings.
 *
 * Returns null when the ordered score is absent, because then there is only
 * one reading left and it is the 61.1% one. A gate that fell back to the weak
 * reading without saying so would look like the measured gate and not be it.
 */
export function verdictOf(answers: Answers, thresholds: Thresholds = DEFAULT_THRESHOLDS): Verdict | null {
  if (!score(answers, "permission").present) return null;
  return Math.max(permissionGate(answers, thresholds), atomicRule(answers)) as Verdict;
}

/** The audit line. Both readings, so a recorded decision can be re-read later
 *  under different cutoffs (docs/19 §4: record/replay). */
export function reasonOf(answers: Answers, verdict: Verdict, thresholds: Thresholds = DEFAULT_THRESHOLDS): string {
